class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # Ensure nums1 is the smaller array to optimize binary search
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        total_len = m + n
        half_len = (total_len + 1) // 2

        left, right = 0, m

        while left <= right:
            i = (left + right) // 2
            j = half_len - i

            # Handle edge cases where partition is at the extreme bounds
            nums1_left_max = float('-inf') if i == 0 else nums1[i - 1]
            nums1_right_min = float('inf') if i == m else nums1[i]
            nums2_left_max = float('-inf') if j == 0 else nums2[j - 1]
            nums2_right_min = float('inf') if j == n else nums2[j]

            # Check if valid partition is found
            if nums1_left_max <= nums2_right_min and nums2_left_max <= nums1_right_min:
                # If total length is odd, return the max of the left halves
                if total_len & 1:
                    return float(max(nums1_left_max, nums2_left_max))
                # If even, return the average of max of left halves and min of right halves
                else:
                    return (max(nums1_left_max, nums2_left_max) + min(nums1_right_min, nums2_right_min)) / 2.0
            elif nums1_left_max > nums2_right_min:
                # i is too far right, move left
                right = i - 1
            else:
                # i is too far left, move right
                left = i + 1

        return 0.0

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)

        # Use 1D DP array to reduce memory from O(m*n) to O(n)
        prev = [False] * (n + 1)
        curr = [False] * (n + 1)

        # Base case: empty string matches empty pattern
        prev[0] = True

        # Initialize first row (empty string s)
        for j in range(2, n + 1):
            if p[j - 1] == '*':
                prev[j] = prev[j - 2]

        # Fill the DP table row by row
        for i in range(1, m + 1):
            curr[0] = False  # Non-empty string can't match empty pattern

            for j in range(1, n + 1):
                if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                    curr[j] = prev[j - 1]
                elif p[j - 1] == '*':
                    # Match zero occurrences
                    curr[j] = curr[j - 2]
                    # Match one or more occurrences
                    if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                        curr[j] = curr[j] or prev[j]
                else:
                    curr[j] = False

            prev, curr = curr, prev

        return prev[n]

class Solution:
    def maxArea(self, height: List[int]) -> int:
        left, right = 0, len(height) - 1
        max_area = 0
        while left < right:
            h_left, h_right = height[left], height[right]
            current_area = min(h_left, h_right) * (right - left)
            if current_area > max_area:
                max_area = current_area
            if h_left < h_right:
                left += 1
            else:
                right -= 1
        return max_area

