class Solution:
    def divide(self, dividend: int, divisor: int) -> int:
        # Handle overflow case
        if dividend == -2**31 and divisor == -1:
            return 2**31 - 1

        # Determine the sign of the result
        negative = (dividend < 0) != (divisor < 0)

        # Work with absolute values
        dividend_abs = abs(dividend)
        divisor_abs = abs(divisor)

        quotient = 0

        while dividend_abs >= divisor_abs:
            temp_divisor = divisor_abs
            multiple = 1
            while dividend_abs >= (temp_divisor << 1):
                if temp_divisor << 1 > dividend_abs:
                    break
                temp_divisor <<= 1
                multiple <<= 1
            dividend_abs -= temp_divisor
            quotient += multiple

        if negative:
            quotient = -quotient

        # Clamp the result to 32-bit signed integer range
        return max(min(quotient, 2**31 - 1), -2**31)

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        if not s:
            return 0

        n = len(s)
        dp = [0] * n
        max_len = 0

        for i in range(1, n):
            if s[i] == ')':
                if s[i - 1] == '(':
                    # Case: "()"
                    dp[i] = (dp[i - 2] if i >= 2 else 0) + 2
                elif i - dp[i - 1] - 1 >= 0 and s[i - dp[i - 1] - 1] == '(':
                    # Case: "))" preceded by a matching "("
                    length = dp[i - 1]
                    prev_len = dp[i - length - 2] if i - length >= 2 else 0
                    dp[i] = length + prev_len + 2

                max_len = max(max_len, dp[i])

        return max_len

