class Solution:
    def combinationSum2(self, candidates, target):
        candidates.sort()
        result = []
        n = len(candidates)

        def backtrack(start, path, remaining):
            if remaining == 0:
                result.append(path[:])
                return
            i = start
            while i < n:
                val = candidates[i]
                if val > remaining:
                    break
                path.append(val)
                backtrack(i + 1, path, remaining - val)
                path.pop()
                i += 1
                while i < n and candidates[i] == val:
                    i += 1

        backtrack(0, [], target)
        return result

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        # Compress consecutive '*' into a single '*' to reduce DP size
        # This significantly optimizes patterns with many redundant '*' wildcards
        compressed_p = []
        last_was_star = False
        for char in p:
            if char == '*':
                if not last_was_star:
                    compressed_p.append(char)
                last_was_star = True
            else:
                compressed_p.append(char)
                last_was_star = False
        p = "".join(compressed_p)

        m, n = len(s), len(p)

        # Use a 1D DP array to save memory
        dp = [False] * (n + 1)
        dp[0] = True

        # Base case: empty string and pattern starting with '*'
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[j] = dp[j - 1]
            else:
                break

        # Fill the DP table
        for i in range(1, m + 1):
            prev = dp[0]
            dp[0] = False  # Empty pattern can't match non-empty string

            for j in range(1, n + 1):
                temp = dp[j]
                if p[j - 1] == '*':
                    # '*' matches empty sequence (dp[j-1]) or matches one/more characters (dp[j])
                    dp[j] = dp[j - 1] or dp[j]
                elif p[j - 1] == '?' or s[i - 1] == p[j - 1]:
                    # Single character match or '?' wildcard
                    dp[j] = prev
                else:
                    dp[j] = False
                prev = temp

        return dp[n]

