        return result

class Solution:
    def totalNQueens(self, n: int) -> int:
        # Precompute the full mask for n columns
        full_mask = (1 << n) - 1

        def backtrack(cols, d1, d2):
            if cols == full_mask:
                return 1

            solutions = 0
            available = full_mask & ~(cols | d1 | d2)

            while available:
                bit = available & -available
                available ^= bit
                solutions += backtrack(cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1)

            return solutions

        return backtrack(0, 0, 0)

