class Solution:
    def canJump(self, nums: List[int]) -> bool:
        max_reach = 0
        n = len(nums)

        for i in range(n):
            # If the current index is greater than the maximum reachable index, we are stuck
            if i > max_reach:
                return False

            # Update the maximum reachable index
            max_reach = max(max_reach, i + nums[i])

            # If we can already reach or surpass the last index, return True early
            if max_reach >= n - 1:
                return True

        return True

