class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        if not intervals:
            return []

        # Sort the intervals by their start times
        intervals.sort(key=lambda x: x[0])

        merged = [intervals[0]]

        for current in intervals[1:]:
            last = merged[-1]
            # If the current interval overlaps with the last merged interval
            if current[0] <= last[1]:
                # Merge them by updating the end time of the last interval
                last[1] = max(last[1], current[1])
            else:
                # If they don't overlap, add the current interval to the result
                merged.append(current)

        return merged

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        if m == 1 or n == 1:
            return 1
        total = m + n - 2
        k = min(m - 1, n - 1)
        res = 1
        for i in range(1, k + 1):
            res = res * (total - k + i) // i
        return res

class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid):
        m = len(obstacleGrid)
        n = len(obstacleGrid[0])

        # If the starting or ending cell is an obstacle, return 0
        if obstacleGrid[0][0] == 1 or obstacleGrid[m-1][n-1] == 1:
            return 0

        # Use a 1D array to save space
        dp = [0] * n
        dp[0] = 1

        # Fill the first row
        for j in range(1, n):
            if obstacleGrid[0][j] == 0:
                dp[j] = dp[j-1]
            else:
                dp[j] = 0

        # Fill the rest of the table
        for i in range(1, m):
            # Handle the first column of the current row
            if obstacleGrid[i][0] == 1:
                dp[0] = 0
            # For the rest of the columns
            for j in range(1, n):
                if obstacleGrid[i][j] == 0:
                    dp[j] += dp[j-1]
                else:
                    dp[j] = 0

        return dp[n-1]

class Solution:
    def addBinary(self, a: str, b: str) -> str:
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        res = []

        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += ord(a[i]) - 48
                i -= 1
            if j >= 0:
                total += ord(b[j]) - 48
                j -= 1

            carry = total >> 1
            res.append(chr((total & 1) + 48))

        return "".join(res[::-1])

class Solution:
    def mySqrt(self, x: int) -> int:
        if x == 0:
            return 0
        if x == 1:
            return 1

        left, right = 0, x // 2 + 1
        result = 0

        while left <= right:
            mid = (left + right) // 2
            squared = mid * mid
            if squared == x:
                return mid
            elif squared < x:
                left = mid + 1
                result = mid
            else:
                right = mid - 1

        return result

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)

        # Handle edge cases for empty strings
        if m == 0:
            return n
        if n == 0:
            return m

        # Ensure word1 is the shorter string to minimize space usage
        if m < n:
            word1, word2 = word2, word1
            m, n = n, m

        # Use a single 1D array to reduce memory overhead
        dp = list(range(n + 1))

        for i in range(1, m + 1):
            prev = dp[0]
            dp[0] = i
            for j in range(1, n + 1):
                temp = dp[j]
                if word1[i - 1] == word2[j - 1]:
                    dp[j] = prev
                else:
                    dp[j] = 1 + min(dp[j], dp[j - 1], prev)
                prev = temp

        return dp[n]

