class Solution:
    def search(self, nums, target):
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                return True

            # Handle duplicates: left, mid, right are same
            if nums[left] == nums[mid] == nums[right]:
                left += 1
                right -= 1
                continue

            # Check if the left half is sorted
            if nums[left] <= nums[mid]:
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1
        return False

class Solution:
    def maximalRectangle(self, matrix):
        if not matrix or not matrix[0]:
            return 0

        rows = len(matrix)
        cols = len(matrix[0])
        heights = [0] * cols
        max_area = 0

        for i in range(rows):
            for j in range(cols):
                if matrix[i][j] == '1':
                    heights[j] += 1
                else:
                    heights[j] = 0

            stack = [-1]
            for j in range(cols + 1):
                current_height = heights[j] if j < cols else 0
                while len(stack) > 1 and current_height < heights[stack[-1]]:
                    h = heights[stack.pop()]
                    w = j - stack[-1] - 1
                    area = h * w
                    if area > max_area:
                        max_area = area
                stack.append(j)

        return max_area

from functools import lru_cache

class Solution:
    @lru_cache(None)
    def isScramble(self, s1: str, s2: str) -> bool:
        # Base case: if the strings are identical, they are trivially scrambles
        if s1 == s2:
            return True

        # Pruning: If the character frequencies don't match, it's impossible to be scrambles
        if sorted(s1) != sorted(s2):
            return False

        n = len(s1)
        # Try all possible split points
        for i in range(1, n):
            # Condition 1: Without swapping
            if self.isScramble(s1[:i], s2[:i]) and self.isScramble(s1[i:], s2[i:]):
                return True

            # Condition 2: With swapping
            if self.isScramble(s1[:i], s2[-i:]) and self.isScramble(s1[i:], s2[:-i]):
                return True

        return False

