class Solution:
    def subsetsWithDup(self, nums):
        nums.sort()
        res = []
        n = len(nums)

        def backtrack(start, path):
            res.append(path[:])
            for i in range(start, n):
                if i > start and nums[i] == nums[i-1]:
                    continue
                path.append(nums[i])
                backtrack(i + 1, path)
                path.pop()

        backtrack(0, [])
        return res

class Solution:
    def numDecodings(self, s: str) -> int:
        if not s or s[0] == '0':
            return 0

        dp_prev2, dp_prev1 = 1, 1

        for i in range(1, len(s)):
            current = 0
            if s[i] != '0':
                current = dp_prev1

            two_char = (ord(s[i-1]) - 48) * 10 + (ord(s[i]) - 48)
            if 10 <= two_char <= 26:
                current += dp_prev2

            dp_prev2, dp_prev1 = dp_prev1, current

        return dp_prev1

class Solution:
    def restoreIpAddresses(self, s: str) -> list[str]:
        res = []
        n = len(s)

        def backtrack(start, path):
            if len(path) == 4:
                if start == n:
                    res.append('.'.join(path))
                return
            remaining = 4 - len(path)
            max_len = min(3, n - start - remaining + 1)
            min_len = max(1, n - start - (remaining - 1) * 3)

            for i in range(min_len, max_len + 1):
                segment = s[start:start+i]
                if segment[0] == '0' and i > 1:
                    continue
                if i == 3 and segment > '255':
                    continue
                backtrack(start + i, path + [segment])

        backtrack(0, [])
        return res

class Solution:
    _catalan = [1, 1]  # Base cases

    def numTrees(self, n: int) -> int:
        # Extend the precomputed Catalan numbers if needed
        while len(self._catalan) <= n:
            current = len(self._catalan)
            count = 0
            for i in range(current):
                count += self._catalan[i] * self._catalan[current - 1 - i]
            self._catalan.append(count)

        return self._catalan[n]

class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        len1, len2, len3 = len(s1), len(s2), len(s3)
        if len1 + len2 != len3:
            return False
        if len1 < len2:
            s1, s2 = s2, s1
            len1, len2 = len2, len1

        dp = [False] * (len2 + 1)
        dp[0] = True

        for j in range(1, len2 + 1):
            dp[j] = dp[j-1] and s2[j-1] == s3[j-1]

        for i in range(1, len1 + 1):
            dp[0] = dp[0] and s1[i-1] == s3[i-1]
            for j in range(1, len2 + 1):
                dp[j] = (dp[j] and s1[i-1] == s3[i+j-1]) or (dp[j-1] and s2[j-1] == s3[i+j-1])

        return dp[len2]

