class Solution:
    def isBalanced(self, root: TreeNode) -> bool:
        def check(node):
            if node is None:
                return 0
            left = check(node.left)
            if left == -1:
                return -1
            right = check(node.right)
            if right == -1 or abs(left - right) > 1:
                return -1
            return (left if left > right else right) + 1
        return check(root) != -1

