    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        result = []
        if not root:
            return result

        stack = [(root, root.val, [root.val])]

        while stack:
            node, current_sum, path = stack.pop()

            if not node.left and not node.right:
                if current_sum == targetSum:
                    result.append(path)
            else:
                if node.right:
                    stack.append((node.right, current_sum + node.right.val, path + [node.right.val]))
                if node.left:
                    stack.append((node.left, current_sum + node.left.val, path + [node.left.val]))

        return result

class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m, n = len(s), len(t)

        if n > m:
            return 0

        dp = [0] * (n + 1)
        dp[0] = 1

        # Precompute character positions in t to skip non-matching characters
        char_positions = {}
        for idx, char in enumerate(t):
            if char not in char_positions:
                char_positions[char] = []
            char_positions[char].append(idx + 1)  # +1 to match dp indexing

        for char_s in s:
            if char_s in char_positions:
                # Traverse backwards through matching positions only
                for j in reversed(char_positions[char_s]):
                    dp[j] += dp[j - 1]

        return dp[n]

