class Solution:
    def partition(self, s: str) -> List[List[str]]:
        res = []
        part = []

        def dfs(i: int):
            # If we have reached the end of the string, append a copy of the current partition to the result
            if i >= len(s):
                res.append(part.copy())
                return

            # Explore all possible substrings starting from index i
            for j in range(i, len(s)):
                # If the substring s[i:j+1] is a palindrome, proceed
                if self.isPalindrome(s, i, j):
                    part.append(s[i:j+1])
                    # Recurse for the remaining string
                    dfs(j + 1)
                    # Backtrack by removing the last added substring
                    part.pop()

        dfs(0)
        return res

    def isPalindrome(self, s: str, l: int, r: int) -> bool:
        # Check if the substring s[l:r+1] is a palindrome using a two-pointer approach
        while l < r:
            if s[l] != s[r]:
                return False
            l, r = l + 1, r - 1
        return True

class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        if n <= 1:
            return 0

        # Use a 1D array for min_cuts
        min_cuts = list(range(n))

        for center in range(n):
            # Odd length palindromes
            left, right = center, center
            while left >= 0 and right < n and s[left] == s[right]:
                if left == 0:
                    min_cuts[right] = 0
                else:
                    min_cuts[right] = min(min_cuts[right], min_cuts[left - 1] + 1)
                left -= 1
                right += 1

            # Even length palindromes
            left, right = center, center + 1
            while left >= 0 and right < n and s[left] == s[right]:
                if left == 0:
                    min_cuts[right] = 0
                else:
                    min_cuts[right] = min(min_cuts[right], min_cuts[left - 1] + 1)
                left -= 1
                right += 1

        return min_cuts[n - 1]

