        # Left to right pass
        for i in range(1, n):
            if ratings[i] > ratings[i-1]:
                candies[i] = candies[i-1] + 1

        # Right to left pass and sum calculation
        total = candies[-1]
        for i in range(n-2, -1, -1):
            if ratings[i] > ratings[i+1]:
                candies[i] = candies[i+1] + 1 if candies[i+1] + 1 > candies[i] else candies[i]
            total += candies[i]

