class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        n = len(prices)

        if n == 0 or k == 0:
            return 0

        if k >= n // 2:
            max_profit = 0
            for i in range(1, n):
                if prices[i] > prices[i - 1]:
                    max_profit += prices[i] - prices[i - 1]
            return max_profit

        prev_unhold = [float('-inf')] * (k + 1)
        prev_hold = [float('-inf')] * (k + 1)

        prev_unhold[0] = 0
        prev_hold[0] = -prices[0]

        for i in range(1, n):
            price = prices[i]
            curr_unhold = [0] + [float('-inf')] * k
            curr_hold = [max(prev_hold[0], -price)] + [float('-inf')] * k

            for j in range(1, k + 1):
                curr_unhold[j] = max(prev_unhold[j], prev_hold[j] + price)
                curr_hold[j] = max(prev_hold[j], prev_unhold[j - 1] - price)

            prev_unhold = curr_unhold
            prev_hold = curr_hold

        return max(prev_unhold)

