class Solution:
    def getSkyline(self, buildings: List[List[int]]) -> List[List[int]]:
        points = []
        for left, right, height in buildings:
            points.append((left, -height, right))
            points.append((right, height, 0))

        points.sort()

        result = []
        heap = [(0, float('inf'))]
        prev_max = 0

        for x, h, r in points:
            if h < 0:
                heapq.heappush(heap, (h, r))
