    def isStrobogrammatic(self, num: str) -> bool:
        # Map each digit to its valid rotated counterpart
        rot = {'0': '0', '1': '1', '6': '9', '8': '8', '9': '6'}

        # Use two pointers to check from both ends towards the center
        left, right = 0, len(num) - 1
        while left <= right:
            # If the digit is not rotatable or doesn't match its counterpart's rotation
            if num[left] not in rot or rot[num[left]] != num[right]:
                return False
            left += 1
            right -= 1
